"""Registration, sign-in and the current user."""

from __future__ import annotations

import re
import sqlite3

from fastapi import APIRouter, Depends, status
from pydantic import BaseModel

from app.config import Settings, get_settings
from app.db import audit, get_db, row_to_dict, utc_now
from app.errors import bad_request, conflict, unauthorized
from app.security import (
 CurrentUser,
 create_access_token,
 get_current_user,
 hash_password,
 password_problem,
 verify_password,
)

router = APIRouter(prefix="/api/auth", tags=["auth"])

USERNAME_RE = re.compile(r"^[A-Za-z0-9_-]{3,32}$")

class Credentials(BaseModel):
 username: str
 password: str

class UserOut(BaseModel):
 id: int
 username: str
 created_at: str

class TokenOut(BaseModel):
 access_token: str
 token_type: str
 expires_in: int

def _user_out(row: sqlite3.Row) -> UserOut:
 return UserOut(id=row["id"], username=row["username"], created_at=row["created_at"])

@router.post("/register", response_model=UserOut, status_code=status.HTTP_201_CREATED, summary="Create an account")
def register(
 body: Credentials,
 conn: sqlite3.Connection = Depends(get_db),
) -> UserOut:
 username = body.username.strip()
 if not USERNAME_RE.match(username):
  raise bad_request("invalid_username", "Username must be 3-32 characters of letters, digits, _ or -.")
 problem = password_problem(body.password)
 if problem is not None:
  raise bad_request("weak_password", problem)
 existing = conn.execute("SELECT id FROM users WHERE username = ?", (username,)).fetchone()
 if existing is not None:
  raise conflict("username_taken", "That username is already taken.")
 created_at = utc_now()
 cur = conn.execute(
  "INSERT INTO users (username, password_hash, created_at) VALUES (?, ?, ?)",
  (username, hash_password(body.password), created_at),
 )
 row = conn.execute("SELECT * FROM users WHERE id = ?", (cur.lastrowid,)).fetchone()
 audit(conn, "register", user_id=cur.lastrowid, detail=username)
 return _user_out(row)

@router.post("/login", response_model=TokenOut, summary="Sign in")
def login(
 body: Credentials,
 conn: sqlite3.Connection = Depends(get_db),
 settings: Settings = Depends(get_settings),
) -> TokenOut:
 row = conn.execute("SELECT * FROM users WHERE username = ?", (body.username.strip(),)).fetchone()
 if row is None or not verify_password(body.password, row["password_hash"]):
  audit(conn, "login_failed", user_id=row["id"] if row is not None else None, detail=body.username.strip())
  raise unauthorized("invalid_credentials", "Wrong username or password.")
 audit(conn, "login", user_id=row["id"], detail=row["username"])
 token = create_access_token(row["id"], row["username"], settings)
 return TokenOut(access_token=token, token_type="bearer", expires_in=settings.token_ttl)

@router.get("/me", response_model=UserOut, summary="The signed-in user")
def me(
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> UserOut:
 row = conn.execute("SELECT * FROM users WHERE id = ?", (user.id,)).fetchone()
 if row is None:
  raise unauthorized()
 return _user_out(row)
```

