"""The signed-in user's personal todos."""

from __future__ import annotations

import sqlite3
from typing import Any

from fastapi import APIRouter, Depends, Query, Response, status
from pydantic import BaseModel

from app.db import get_db, utc_now
from app.errors import bad_request, not_found
from app.pagination import PageParams, page_params, paginate
from app.security import CurrentUser, get_current_user

router = APIRouter(prefix="/api/todos", tags=["todos"])

TITLE_MAX = 200

class TodoOut(BaseModel):
 id: int
 title: str
 done: bool
 created_at: str
 updated_at: str

class TodoCreate(BaseModel):
 title: str

class TodoUpdate(BaseModel):
 title: str | None = None
 done: bool | None = None

def _todo_out(row: sqlite3.Row) -> TodoOut:
 return TodoOut(
  id=row["id"],
  title=row["title"],
  done=bool(row["done"]),
  created_at=row["created_at"],
  updated_at=row["updated_at"],
 )

def _clean_title(title: str) -> str:
 cleaned = title.strip()
 if not cleaned or len(cleaned) > TITLE_MAX:
  raise bad_request("invalid_title", f"Title must be 1-{TITLE_MAX} characters.")
 return cleaned

def _own_todo(conn: sqlite3.Connection, user_id: int, todo_id: int) -> sqlite3.Row:
 row = conn.execute(
  "SELECT * FROM todos WHERE id = ? AND user_id = ?", (todo_id, user_id)
 ).fetchone()
 if row is None:
  raise not_found("todo_not_found", "Todo not found.")
 return row

@router.get("", summary="List todos")
def list_todos(
 done: bool | None = Query(default=None, description="Filter by done state."),
 page: PageParams = Depends(page_params),
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> dict[str, Any]:
 where = "user_id = ?"
 params: list[Any] = [user.id]
 if done is not None:
  where += " AND done = ?"
  params.append(1 if done else 0)
 total = conn.execute(f"SELECT COUNT(*) FROM todos WHERE {where}", params).fetchone()[0]
 rows = conn.execute(
  f"SELECT * FROM todos WHERE {where} ORDER BY created_at DESC, id DESC LIMIT ? OFFSET ?",
  [*params, page.limit, page.offset],
 ).fetchall()
 return paginate([_todo_out(r) for r in rows], total, page)

@router.post("", response_model=TodoOut, status_code=status.HTTP_201_CREATED, summary="Add a todo")
def create_todo(
 body: TodoCreate,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
 title = _clean_title(body.title)
 now = utc_now()
 cur = conn.execute(
  "INSERT INTO todos (user_id, title, done, created_at, updated_at) VALUES (?, ?, 0, ?, ?)",
  (user.id, title, now, now),
 )
 row = conn.execute("SELECT * FROM todos WHERE id = ?", (cur.lastrowid,)).fetchone()
 return _todo_out(row)

@router.get("/{todo_id}", response_model=TodoOut, summary="One todo")
def get_todo(
 todo_id: int,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
 return _todo_out(_own_todo(conn, user.id, todo_id))

@router.patch("/{todo_id}", response_model=TodoOut, summary="Change a todo")
def update_todo(
 todo_id: int,
 body: TodoUpdate,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
 row = _own_todo(conn, user.id, todo_id)
 title = row["title"]
 done = row["done"]
 if body.title is not None:
  title = _clean_title(body.title)
 if body.done is not None:
  done = 1 if body.done else 0
 conn.execute(
  "UPDATE todos SET title = ?, done = ?, updated_at = ? WHERE id = ? AND user_id = ?",
  (title, done, utc_now(), todo_id, user.id),
 )
 return _todo_out(_own_todo(conn, user.id, todo_id))

@router.delete("/{todo_id}", status_code=status.HTTP_204_NO_CONTENT, summary="Delete a todo")
def delete_todo(
 todo_id: int,
 user: CurrentUser = Depends(get_current_user),
 conn: sqlite3.Connection = Depends(get_db),
) -> Response:
 _own_todo(conn, user.id, todo_id)
 conn.execute("DELETE FROM todos WHERE id = ? AND user_id = ?", (todo_id, user.id))
 return Response(status_code=status.HTTP_204_NO_CONTENT)
```

