import { apiFetch, ApiError, saveToken, isSignedIn } from "./api.js";
import { formValues, showMessage, whileBusy } from "./ui.js";

if (isSignedIn()) {
window.location.replace("todos.html");
}

function errorText(error) {
return error instanceof ApiError ? error.message : "The service cannot be reached.";
}

const loginForm = document.getElementById("login-form");
const registerForm = document.getElementById("register-form");

loginForm.addEventListener("submit", async (event) => {
event.preventDefault();
await whileBusy(loginForm, async () => {
try {
const values = formValues(loginForm);
const result = await apiFetch("/api/auth/login", { method: "POST", body: values, auth: false });
saveToken(result.access_token);
window.location.assign("todos.html");
} catch (error) {
showMessage(errorText(error), "error");
}
});
});

registerForm.addEventListener("submit", async (event) => {
event.preventDefault();
await whileBusy(registerForm, async () => {
try {
const values = formValues(registerForm);
await apiFetch("/api/auth/register", { method: "POST", body: values, auth: false });
const result = await apiFetch("/api/auth/login", { method: "POST", body: values, auth: false });
saveToken(result.access_token);
window.location.assign("todos.html");
} catch (error) {
showMessage(errorText(error), "error");
