import { apiFetch, ApiError, clearToken, isSignedIn, loadToken } from "./api.js";
import { clear, el, formatTime, showMessage, whileBusy } from "./ui.js";

if (!isSignedIn()) {
window.location.replace("login.html");
}

const PAGE_SIZE = 20;

const listNode = document.getElementById("list");
const filterNode = document.getElementById("filter");
const prevNode = document.getElementById("prev");
const nextNode = document.getElementById("next");
const addForm = document.getElementById("add-form");
const whoNode = document.getElementById("who");

let offset = 0;
let total = 0;

function errorText(error) {
return error instanceof ApiError ? error.message : "The service cannot be reached.";
}

function signOut() {
clearToken();
window.location.replace("login.html");
}

document.getElementById("signout").addEventListener("click", signOut);

async function loadMe() {
try {
const me = await apiFetch("/api/auth/me");
whoNode.textContent = me.username;
} catch (error) {
if (error instanceof ApiError && error.status === 401) {
signOut();
return;
}
showMessage(errorText(error), "error");
}
}

async function toggle(todo) {
try {
await apiFetch(`/api/todos/${todo.id}`, { method: "PATCH", body: { done: !todo.done } });
await load();
} catch (error) {
showMessage(errorText(error), "error");
}
}

async function rename(todo) {
const title = window.prompt("New title", todo.title);
if (title === null) return;
try {
await apiFetch(`/api/todos/${todo.id}`, { method: "PATCH", body: { title } });
await load();
} catch (error) {
showMessage(errorText(error), "error");
}
}

async function remove(todo) {
if (!window.confirm(`Delete "${todo.title}"?`)) return;
try {
await apiFetch(`/api/todos/${todo.id}`, { method: "DELETE" });
if (offset > 0 && offset >= total - 1) offset = Math.max(0, offset - PAGE_SIZE);
await load();
} catch (error) {
showMessage(errorText(error), "error");
}
}

function renderItem(todo) {
const checkbox = el("input", { type: "checkbox" });
checkbox.checked = todo.done;
checkbox.addEventListener("change", () => toggle(todo));
const title = el("span", { class: "title" }, todo.title);
const meta = el("span", { class: "muted" }, formatTime(todo.created_at));
const renameBtn = el("button", { type: "button", class: "secondary" }, "Rename");
renameBtn.addEventListener("click", () => rename(todo));
const deleteBtn = el("button", { type: "button", class: "danger" }, "Delete");
deleteBtn.addEventListener("click", () => remove(todo));
return el(
"div",
{ class: todo.done ? "list-item done" : "list-item" },
checkbox,
el("div", { class: "grow" }, title, meta),
renameBtn,
deleteBtn,
);
}

async function load() {
const query = { limit: PAGE_SIZE, offset };
if (filterNode.value) query.done = filterNode.value;
try {
const page = await apiFetch("/api/todos", { query });
total = page.total;
clear(listNode);
if (page.items.length === 0) {
listNode.append(el("p", { class: "muted" }, "No todos yet."));
} else {
for (const todo of page.items) listNode.append(renderItem(todo));
}
prevNode.disabled = offset <= 0;
nextNode.disabled = offset + PAGE_SIZE >= total;
} catch (error) {
if (error instanceof ApiError && error.status === 401) {
signOut();
return;
}
showMessage(errorText(error), "error");
}
}

prevNode.addEventListener("click", () => {
offset = Math.max(0, offset - PAGE_SIZE);
load();
});

nextNode.addEventListener("click", () => {
offset += PAGE_SIZE;
load();
});

filterNode.addEventListener("change", () => {
offset = 0;
load();
});

addForm.addEventListener("submit", async (event) => {
event.preventDefault();
await whileBusy(addForm, async () => {
try {
const title = document.getElementById("add-title").value.trim();
await apiFetch("/api/todos", { method: "POST", body: { title } });
addForm.reset();
offset = 0;
await load();
} catch (error) {
showMessage(errorText(error), "error");
}
});
});

if (loadToken()) {
loadMe();
load();
}
